import React, { useState } from 'react';
import Project from './Project';
import data from './../data/projectsData.js';
import { FaFilter, FaExternalLinkAlt, FaGithub } from 'react-icons/fa';

function Projects() {
  const [activeFilter, setActiveFilter] = useState('All');

  // Get unique categories from projects
  const categories = ['All', ...new Set(data.ProjectsData.map(project => project.category))];

  // Filter projects based on active category
  const filteredProjects = activeFilter === 'All' 
    ? data.ProjectsData 
    : data.ProjectsData.filter(project => project.category === activeFilter);

  return (
    <section id='projects' className='py-20 px-6 sm:px-8 lg:px-12'>
      <div className="max-w-7xl mx-auto">
        {/* Section Header */}
        <div className="text-center mb-20">
          <h2 className="heading-primary text-5xl sm:text-6xl md:text-7xl font-bold text-white mb-8">
            My <span className="text-[#6699CC]">Projects</span>
          </h2>
          <div className="w-32 h-1.5 bg-[#6699CC] mx-auto rounded-full mb-8"></div>
          <p className="text-body text-gray-300 text-xl sm:text-2xl max-w-4xl mx-auto leading-relaxed">
            A curated showcase of my recent work, featuring innovative solutions and creative implementations
          </p>
        </div>

        {/* Category Filter */}
        <div className="flex flex-wrap justify-center items-center gap-4 mb-16">
          <FaFilter className="text-[#6699CC] text-2xl mr-3" />
          <span className="text-accent text-gray-400 text-lg mr-4">Filter by:</span>
          {categories.map((category) => (
            <button
              key={category}
              onClick={() => setActiveFilter(category)}
              className={`px-8 py-4 rounded-full font-medium transition-all duration-300 text-lg ${
                activeFilter === category
                  ? 'bg-[#6699CC] text-[#20262E] shadow-lg scale-105'
                  : 'bg-gray-800/50 text-gray-300 hover:bg-gray-700/50 hover:text-white hover:scale-105'
              }`}
            >
              {category}
            </button>
          ))}
        </div>

        {/* Projects Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
          {filteredProjects.map((project) => (
            <EnhancedProjectCard key={project.id} project={project} />
          ))}
        </div>


      </div>
    </section>
  );
}

// Enhanced Project Card Component
function EnhancedProjectCard({ project }) {
  return (
    <div className="bg-gray-800/50 rounded-2xl border border-gray-700/50 overflow-hidden hover:border-[#6699CC]/50 transition-all duration-300 group">
      {/* Project Image */}
      <div className="relative overflow-hidden">
        <img 
          src={project.img} 
          alt={project.name}
          className="w-full h-48 object-cover transition-transform duration-300 group-hover:scale-110"
        />
        <div className="absolute top-4 right-4">
          <span className={`px-3 py-1 rounded-full text-xs font-medium ${
            project.status === 'Completed' ? 'bg-green-500/20 text-green-400' :
            project.status === 'In Production' ? 'bg-blue-500/20 text-blue-400' :
            'bg-yellow-500/20 text-yellow-400'
          }`}>
            {project.status}
          </span>
        </div>
      </div>

      {/* Project Content */}
      <div className="p-6 space-y-4">
        <div className="flex items-start justify-between">
          <h3 className="text-xl font-bold text-white group-hover:text-[#6699CC] transition-colors duration-300">
            {project.name}
          </h3>
          <span className="px-3 py-1 bg-[#6699CC]/20 text-[#6699CC] text-xs rounded-full">
            {project.category}
          </span>
        </div>

        <p className="text-gray-300 text-sm leading-relaxed">
          {project.description}
        </p>

        {/* Tech Stack */}
        <div className="flex flex-wrap gap-2">
          {project.stack.map((tech, index) => (
            <span key={index} className="px-3 py-1 bg-gray-700/50 text-gray-300 text-xs rounded-full">
              {tech}
            </span>
          ))}
        </div>

        {/* Project Details */}
        <div className="grid grid-cols-2 gap-4 text-sm">
          <div>
            <span className="text-gray-400">Duration:</span>
            <p className="text-white font-medium">{project.duration}</p>
          </div>
          <div>
            <span className="text-gray-400">Team:</span>
            <p className="text-white font-medium">{project.teamSize}</p>
          </div>
        </div>

        {/* Project Links */}
        <div className="flex space-x-4 pt-4">
          {project.live && (
            <a
              href={project.live}
              target="_blank"
              rel="noopener noreferrer"
              className="flex items-center space-x-2 px-4 py-2 bg-[#6699CC] text-[#20262E] rounded-lg hover:bg-[#5C4DCE] transition-colors duration-300 font-medium"
            >
              <FaExternalLinkAlt size={14} />
              <span>Live Demo</span>
            </a>
          )}
          {project.source && (
            <a
              href={project.source}
              target="_blank"
              rel="noopener noreferrer"
              className="flex items-center space-x-2 px-4 py-2 border border-gray-600 text-gray-300 rounded-lg hover:border-[#6699CC] hover:text-white transition-all duration-300"
            >
              <FaGithub size={14} />
              <span>Source</span>
            </a>
          )}
        </div>
      </div>
    </div>
  );
}

export default Projects;
